import UIKit
class ViewController: UIViewController {
    override func viewDidLoad() {
        super.viewDidLoad()

        // Create a square view
        let squareView = UIView(frame: CGRect(x: 100, y: 100, width: 100, height: 100))
        squareView.backgroundColor = UIColor.blue
        self.view.addSubview(squareView)

        // Create a basic animation
        let rotationAnimation = CABasicAnimation(keyPath: "transform.rotation.z")
        rotationAnimation.toValue = NSNumber(value: Double.pi * 2)
        rotationAnimation.duration = 1.0
        rotationAnimation.repeatCount = Float.infinity

        // Add the animation to the square view's layer
        squareView.layer.add(rotationAnimation, forKey: "rotationAnimation")
    }
}
```
This code creates a square view and applies a rotation animation to it using Core Animation. Other tools can similarly be implemented in Swift to create a visually appealing and innovative product design guide.

