```
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
string soundex(string word) {
    string soundex_code = "";
    soundex_code += toupper(word[0]);
    string soundex_map = "01230120022455012623010202";
    for (int i = 1; i < word.length(); i++) {
        char c = toupper(word[i]);
        char prev = toupper(word[i - 1]);
        if (soundex_map[c - 'A'] != '0' && soundex_map[c - 'A'] != soundex_map[prev - 'A']) {
            soundex_code += soundex_map[c - 'A'];
        }
    }
    soundex_code.erase(remove(soundex_code.begin() + 1, soundex_code.end(), '0'), soundex_code.end());
    soundex_code.resize(4, '0');
    return soundex_code;
}
int main() {
    string target_word = "bay";
    string target_soundex = soundex(target_word);
    vector<string> words = {"bey", "beigh", "baye", "bae", "baigh"};
    for (string word : words) {
        string soundex_code = soundex(word);
        if (soundex_code == target_soundex) {
            cout << word << ": explanation" << endl;
        }
    }
    return 0;
}
```
