As for implementing these techniques in a neural network using Scala code, here's an example of using a genetic algorithm to optimize a neural network:
```
import org.encog.Encog
import org.encog.engine.network.activation.ActivationSigmoid
import org.encog.ml.data.MLData
import org.encog.ml.data.basic.BasicMLData
import org.encog.ml.ea.genome.Genome
import org.encog.ml.ea.train.basic.TrainEA
import org.encog.neural.networks.BasicNetwork
import org.encog.neural.networks.layers.BasicLayer
import org.encog.neural.networks.training.TrainingSetScore
import org.encog.util.simple.EncogUtility
import scala.collection.JavaConversions._
object NeuralNetworkGA {
  def main(args: Array[String]) {
    val input = new BasicLayer(null, true, 2)
    val hidden = new BasicLayer(new ActivationSigmoid(), true, 4)
    val output = new BasicLayer(new ActivationSigmoid(), false, 1)
    val network = new BasicNetwork()
    network.addLayer(input)
    network.addLayer(hidden)
    network.addLayer(output)
    network.getStructure().finalizeStructure()
    network.reset()
    val trainingSet = EncogUtility.loadCSV2Memory("1,1,0\n0,0,0\n1,0,1\n0,1,1")
    val score = new TrainingSetScore(trainingSet)
    val train = new TrainEA(network, score)
    train.addOperation(0.9, new MutatePerturb())
    train.addOperation(0.1, new MutateAddNode())
    train.addOperation(0.1, new MutateAddLink())
    train.addOperation(0.05, new MutateRemoveNode())
    train.addOperation(0.05, new MutateRemoveLink())
    train.addOperation(0.05, new MutateSwap())
    train.addOperation(0.05, new MutateActivation())
    train.addOperation(0.05, new MutateWeight())
    var epoch = 1
    while(true) {
      train.iteration()
      System.out.println("Epoch #" + epoch + " Score:" + train.getError())
      epoch += 1
      if(train.getError() < 0.01)
        break
    }
    Encog.getInstance().shutdown()
  }
  class MutatePerturb extends MutateWeight {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val weights = network.getFlat().getWeights()
      for(i <- 0 to weights.length - 1) {
        if(Math.random() < getMutationProbability()) {
          weights(i) += (Math.random() - 0.5) * getMutationRange() * 2
        }
      }
    }
  }
  class MutateAddNode extends MutateAddLink {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val fromLayer = Math.floor(Math.random() * network.getLayerCount()).asInstanceOf[Int]
      val toLayer = Math.floor(Math.random() * network.getLayerCount()).asInstanceOf[Int]
      val fromNeuron = Math.floor(Math.random() * network.getLayerNeuronCount(fromLayer)).asInstanceOf[Int]
      val toNeuron = Math.floor(Math.random() * network.getLayerNeuronCount(toLayer)).asInstanceOf[Int]
      val newLayer = new BasicLayer(new ActivationSigmoid(), true, 1)
      network.addLayer(fromLayer + 1, newLayer)
      network.addConnection(fromLayer, fromNeuron, fromLayer + 1, 0, Math.random() * 2 - 1)
      network.addConnection(fromLayer + 1, 0, toLayer, toNeuron, Math.random() * 2 - 1)
    }
  }
  class MutateAddLink extends MutateRemoveLink {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val fromLayer = Math.floor(Math.random() * network.getLayerCount()).asInstanceOf[Int]
      val toLayer = Math.floor(Math.random() * network.getLayerCount()).asInstanceOf[Int]
      val fromNeuron = Math.floor(Math.random() * network.getLayerNeuronCount(fromLayer)).asInstanceOf[Int]
      val toNeuron = Math.floor(Math.random() * network.getLayerNeuronCount(toLayer)).asInstanceOf[Int]
      network.addConnection(fromLayer, fromNeuron, toLayer, toNeuron, Math.random() * 2 - 1)
    }
  }
  class MutateRemoveNode extends MutateRemoveLink {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val layer = Math.floor(Math.random() * (network.getLayerCount() - 2) + 1).asInstanceOf[Int]
      network.deleteLayer(layer)
    }
  }
  class MutateRemoveLink extends MutateWeight {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val connections = network.getFlat().getConnections()
      val index = Math.floor(Math.random() * connections.length).asInstanceOf[Int]
      network.getFlat().deleteConnection(index)
    }
  }
  class MutateSwap extends MutateWeight {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val connections = network.getFlat().getConnections()
      val index1 = Math.floor(Math.random() * connections.length).asInstanceOf[Int]
      val index2 = Math.floor(Math.random() * connections.length).asInstanceOf[Int]
      val temp = connections(index1).getWeight()
      connections(index1).setWeight(connections(index2).getWeight())
      connections(index2).setWeight(temp)
    }
  }
  class MutateActivation extends MutateWeight {
    override def mutate(genome: Genome) {
      val network = genome.getOrganism().asInstanceOf[BasicNetwork]
      val layers = network.getLayers()
      val index1 = Math.floor(Math.random() * layers.length).asInstanceOf[Int]
      val index2 = Math.floor(Math.random() * layers(index1).getNeuronCount()).asInstanceOf[Int]
      layers(index1).setActivationFunction(index2, new ActivationSigmoid())
    }
  }
}
```
This code uses a genetic algorithm to optimize a neural network with two input neurons, four hidden neurons, and one output neuron. The network is trained on a dataset of logical XOR operations. The genetic algorithm uses various mutation operations to modify the network's structure and weights to improve its performance on the training set.

