What is the formula to calculate the frequency of words in a given text and display the top 5 most common words associated with the theme of "learning"? 
[Formula]: freq(word) = (number of occurrences of word in text) / (total number of words in text)
[Go code]:
package main
import (
	"fmt"
	"strings"
	"sort"
)
func main() {
	// Input text to be analyzed
	text := "Learning is the process of acquiring new knowledge, skills, and values through experience, study, or instruction. It can happen at any time in life and can take many different forms."
	// Words to be excluded from analysis
	exclude := []string{"the", "of", "and", "or", "it", "can", "at", "any", "in", "a", "many"}
	// Split text into individual words
	words := strings.Fields(text)
	// Create map to store word frequencies
	freq := make(map[string]float64)
	// Iterate over words, count frequency
	for _, word := range words {
		if !contains(exclude, word) {
			freq[word]++
		}
	}
	// Calculate word frequencies
	for word := range freq {
		freq[word] = freq[word] / float64(len(words))
	}
	// Sort words by frequency
	sorted := make([]string, 0, len(freq))
	for word := range freq {
		sorted = append(sorted, word)
	}
	sort.Slice(sorted, func(i, j int) bool {
		return freq[sorted[i]] > freq[sorted[j]]
	})
	// Print top 5 most common words
	fmt.Println("Top 5 most common words associated with learning:")
	for i := 0; i < 5; i++ {
		fmt.Printf("%d. %s (%.2f frequency)\n", i+1, sorted[i], freq[sorted[i]])
	}
}
// Helper function to check if a string exists in a slice
func contains(slice []string, str string) bool {
	for _, item := range slice {
		if item == str {
			return true
		}
	}
	return false
}

