// Define metrics for each factor
const accessibilityMetric = 0.1; // 10% increase in accessibility
const qualityMetric = 0.05; // 5% increase in quality
const retentionMetric = 0.03; // 3% increase in retention
const recruitmentMetric = 0.02; // 2% increase in recruitment
const infrastructureMetric = 0.07; // 7% increase in infrastructure
const technologyMetric = 0.05; // 5% increase in technology
// Define a function to calculate the impact for each institution
function calculateImpact(institution, budgetIncrease) {
  let accessibilityIncrease = 0;
  let qualityIncrease = 0;
  let retentionIncrease = 0;
  let recruitmentIncrease = 0;
  let infrastructureIncrease = 0;
  let technologyIncrease = 0;
  // Calculate accessibility and quality based on institution data
  if (institution.region === 'East' && institution.demographic === 'High Income') {
    accessibilityIncrease = budgetIncrease * accessibilityMetric * 1.2; // 20% increase for high-income regions in the East
    qualityIncrease = budgetIncrease * qualityMetric * 1.1; // 10% increase for high-income regions in the East
  } else if (institution.region === 'West' && institution.demographic === 'Low Income') {
    accessibilityIncrease = budgetIncrease * accessibilityMetric * 1.3; // 30% increase for low-income regions in the West
    qualityIncrease = budgetIncrease * qualityMetric * 1.2; // 20% increase for low-income regions in the West
  } else {
    accessibilityIncrease = budgetIncrease * accessibilityMetric;
    qualityIncrease = budgetIncrease * qualityMetric;
  }
  // Calculate retention and recruitment based on institution data
  if (institution.demographic === 'High Income') {
    retentionIncrease = budgetIncrease * retentionMetric * 1.1; // 10% increase for high-income institutions
    recruitmentIncrease = budgetIncrease * recruitmentMetric * 1.2; // 20% increase for high-income institutions
  } else if (institution.demographic === 'Low Income') {
    retentionIncrease = budgetIncrease * retentionMetric * 1.2; // 20% increase for low-income institutions
    recruitmentIncrease = budgetIncrease * recruitmentMetric * 1.1; // 10% increase for low-income institutions
  } else {
    retentionIncrease = budgetIncrease * retentionMetric;
    recruitmentIncrease = budgetIncrease * recruitmentMetric;
  }
  // Calculate infrastructure and technology based on institution data
  if (institution.region === 'North') {
    infrastructureIncrease = budgetIncrease * infrastructureMetric * 1.1; // 10% increase for institutions in the North
    technologyIncrease = budgetIncrease * technologyMetric * 1.2; // 20% increase for institutions in the North
  } else if (institution.region === 'South') {
    infrastructureIncrease = budgetIncrease * infrastructureMetric * 1.2; // 20% increase for institutions in the South
    technologyIncrease = budgetIncrease * technologyMetric * 1.1; // 10% increase for institutions in the South
  } else {
    infrastructureIncrease = budgetIncrease * infrastructureMetric;
    technologyIncrease = budgetIncrease * technologyMetric;
  }
  // Calculate total impact for the institution
  const totalImpact = {
    accessibility: accessibilityIncrease,
    quality: qualityIncrease,
    retention: retentionIncrease,
    recruitment: recruitmentIncrease,
    infrastructure: infrastructureIncrease,
    technology: technologyIncrease
  };
  return totalImpact;
}
