```
public class Customer
{
    public string Name { get; set; }
    public int Points { get; set; }
    public List<Reward> Rewards { get; set; }
}
public class Reward
{
    public string Name { get; set; }
    public int PointsRequired { get; set; }
    public bool IsRedeemed { get; set; }
}
public class LoyaltyProgram
{
    private List<Customer> customers;

    public LoyaltyProgram()
    {
        customers = new List<Customer>();
    }

    public void AddCustomer(Customer customer)
    {
        customers.Add(customer);
    }

    public void AddPoints(Customer customer, int points)
    {
        customer.Points += points;
    }

    public void RedeemReward(Customer customer, Reward reward)
    {
        if (customer.Points >= reward.PointsRequired && !reward.IsRedeemed)
        {
            customer.Points -= reward.PointsRequired;
            reward.IsRedeemed = true;
            customer.Rewards.Add(reward);
        }
    }
}
```
