// Define a function to calculate the expertise score for a particular area of expertise
double calculateExpertiseScore(ExpertiseData expertise) {
    // Calculate the average of the data points
    double sum = 0;
    for (int i = 0; i < expertise.dataPoints.size(); i++) {
        sum += expertise.dataPoints[i];
    }
    double average = sum / expertise.dataPoints.size();

    // Calculate the standard deviation of the data points
    double variance = 0;
    for (int i = 0; i < expertise.dataPoints.size(); i++) {
