package main
import (
    "fmt"
    "gonum.org/v1/gonum/mat"
    "github.com/mjibson/go-dsp/gaussian"
    "math/rand"
)
func main() {
    // create data
    data := make([]float64, 1000)
    for i := range data {
        data[i] = rand.NormFloat64()
    }
    // create mixture model
    k := 2
    mixture := make([]gaussian.Gaussian, k)
    for i := range mixture {
        mixture[i] = gaussian.Gaussian{
            Mu: rand.NormFloat64(),
            Sigma: rand.Float64(),
            Weight: 1.0 / float64(k),
        }
    }
    // create data matrix
    matData := mat.NewDense(len(data), 1, data)
    // fit mixture model
    for i := 0; i < 100; i++ {
        mixture = gaussian.Fit(mixture, matData)
    }
    // print results
    fmt.Println(mixture)
}
