```
function selectionSort(arr) {
  for (let i = 0; i < arr.length - 1; i++) {
    let minIndex = i;
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[j] < arr[minIndex]) {
        minIndex = j;
      }
    }
    if (minIndex != i) {
      let temp = arr[i];
      arr[i] = arr[minIndex];
      arr[minIndex] = temp;
    }
  }
  return arr;
}

// Example usage:
let arr = [5, 3, 6, 2, 10];
let sortedArr = selectionSort(arr);
console.log(sortedArr); // Output: [2, 3, 5, 6, 10]
```

The above code implements selection sort. It starts by iterating through the array and finding the minimum element in the remaining unsorted part of the array. It then swaps the minimum element with the first element of the unsorted part. It repeats this process until the entire array is sorted.

